DROP TABLE IF EXISTS `vue_etat_stocks`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vue_etat_stocks` AS select `sm`.`id` AS `id`,`sm`.`magasin_id` AS `magasin_id`,`m`.`Nom_Magasin` AS `nom_magasin`,`sm`.`article_id` AS `article_id`,`a`.`LIBELLE` AS `libelle_article`,`a`.`Code_Barres` AS `code_barres`,`a`.`Prix_TTC1` AS `prix_vente_ttc`,`sm`.`quantite_stock` AS `quantite_actuelle`,`sm`.`seuil_min` AS `seuil_min`,`sm`.`seuil_max` AS `seuil_max`,(case when ((`sm`.`seuil_min` is not null) and (`sm`.`quantite_stock` <= `sm`.`seuil_min`)) then 'CRITIQUE' when ((`sm`.`seuil_min` is not null) and (`sm`.`quantite_stock` <= (`sm`.`seuil_min` * 1.2))) then 'FAIBLE' when ((`sm`.`seuil_max` is not null) and (`sm`.`quantite_stock` >= `sm`.`seuil_max`)) then 'EXCESSIF' else 'NORMAL' end) AS `niveau_alerte`,0 AS `ventes_30_jours` from ((`stock_magasin` `sm` left join `magasin` `m` on((`sm`.`magasin_id` = `m`.`id`))) left join `articles` `a` on((`sm`.`article_id` = `a`.`ARCLEUNIK`)));


DROP TABLE IF EXISTS `vue_mouvements_stock`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vue_mouvements_stock` AS select `v`.`VTCLEUNIK` AS `vente_id`,1 AS `article_id`,1 AS `quantite_vendue`,`v`.`Date` AS `date_mouvement`,'VENTE' AS `type_mouvement`,`m`.`id` AS `magasin_id`,`m`.`Nom_Magasin` AS `nom_magasin`,'VENTE GENERIQUE' AS `libelle_article`,'GEN001' AS `code_barres`,cast(0.00 as decimal(10,2)) AS `prix_unitaire`,cast(0.00 as decimal(10,2)) AS `montant_total`,`v`.`Client_Nom` AS `reference_client` from (`ventes` `v` left join `magasin` `m` on((`v`.`Code_magasin` = `m`.`id`))) where (`v`.`Date` is not null) order by `v`.`Date` desc;


DROP TABLE IF EXISTS `vue_stocks_complets`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vue_stocks_complets` AS select `sm`.`id` AS `stock_id`,`sm`.`magasin_id` AS `magasin_id`,`m`.`Code_Magasin` AS `code_magasin`,`m`.`Nom_Magasin` AS `nom_magasin`,`sm`.`article_id` AS `article_id`,`a`.`LIBELLE` AS `libelle_article`,`a`.`Code_Barres` AS `code_barres`,`a`.`Prix_TTC1` AS `prix_vente_ttc`,coalesce(`a`.`Prix_Achat_HT`,0) AS `prix_achat_ht`,`sm`.`quantite_stock` AS `quantite_stock`,`sm`.`seuil_min` AS `seuil_min`,`sm`.`seuil_max` AS `seuil_max`,(case when ((`sm`.`seuil_min` is not null) and (`sm`.`quantite_stock` <= `sm`.`seuil_min`)) then 'CRITIQUE' when ((`sm`.`seuil_min` is not null) and (`sm`.`quantite_stock` <= (`sm`.`seuil_min` * 1.2))) then 'FAIBLE' when ((`sm`.`seuil_max` is not null) and (`sm`.`quantite_stock` >= `sm`.`seuil_max`)) then 'EXCESSIF' else 'NORMAL' end) AS `niveau_alerte`,(`sm`.`quantite_stock` * `a`.`Prix_TTC1`) AS `valeur_stock_ttc`,(`a`.`Prix_TTC1` - coalesce(`a`.`Prix_Achat_HT`,0)) AS `marge_unitaire`,(`sm`.`quantite_stock` * (`a`.`Prix_TTC1` - coalesce(`a`.`Prix_Achat_HT`,0))) AS `marge_totale`,now() AS `date_maj`,0 AS `ventes_30_jours` from ((`stock_magasin` `sm` left join `magasin` `m` on((`sm`.`magasin_id` = `m`.`id`))) left join `articles` `a` on((`sm`.`article_id` = `a`.`ARCLEUNIK`))) where (`sm`.`article_id` is not null) order by `m`.`Nom_Magasin`,`a`.`LIBELLE`;


